def select_preprocessing(data_dist, missing_type, is_imbalanced):
    res = {}
    res['outlier'] = 'IQR (Q1-1.5IQR)' if data_dist == 'skewed' else 'Z-Score (|Z|>3)'
    res['impute'] = 'Median' if data_dist == 'skewed' else 'Mean'
    res['imbalance'] = 'SMOTE (Train ONLY) + Cost-Sensitive' if is_imbalanced else 'None'
    return res

def diagnose_and_fix(train_loss, val_loss):
    gap = val_loss - train_loss
    if train_loss > 0.3 and val_loss > 0.3:
        return "High Bias (欠擬合) ➔ 處方：加深模型、加特徵、降 L2"
    elif gap > 0.2:
        return "High Variance (過擬合) ➔ 處方：加資料、加 Dropout、加 L2、Early Stop"
    else:
        return "Good Fit (完美擬合) ➔ 處方：保持現狀，準備上線！"

